/**
 * VAPID Worker secrets (ADR-0102) — declared here, NOT hand-edited into
 * `worker-configuration.d.ts`, because that file is REGENERATED by
 * `wrangler types` and manual edits would be wiped. Secrets are set with
 * `wrangler secret put` (they are bindings the config file does not
 * declare), so this augmentation is the type's home. All optional: a
 * deployment with no VAPID secrets has the push feature silently off —
 * the DO reads them as `undefined` and builds no fan-out sender.
 */
declare global {
  interface Env {
    VAPID_PUBLIC_KEY?: string
    VAPID_PRIVATE_KEY?: string
    /** `mailto:` contact for the VAPID JWT's `sub` claim (RFC 8292). */
    VAPID_SUBJECT?: string
  }
}

export {}
